head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
scwin._triggerKeyboardEvent = function(el, keyCode) {
	var eventObj = document.createEventObject ?
		document.createEventObject() : document.createEvent("Events");
	if (eventObj.initEvent) {
		eventObj.initEvent("keydown", true, true);
	}
	eventObj.keyCode = keyCode;
	eventObj.which = keyCode;
	el.dispatchEvent ? el.dispatchEvent(eventObj) : el.fireEvent("onkeydown", eventObj);
};
scwin.callFun1 = function() {
	scwin._triggerKeyboardEvent(scwin.__getDom($p.id + 'autoComplete1_label'), 13);
};
scwin.callFun2 = function() {
	scwin._triggerKeyboardEvent(scwin.__getDom($p.id + 'autoComplete1_input'), 13);
};
scwin.onpageload = function() {
	window.jsonData = [{
			"value": "G",
			"label": "[400] G"
		},
		{
			"value": "Y1",
			"label": "[300] UY"
		},
		{
			"value": "Y2",
			"label": "[200] UY2"
		},
		{
			"value": "N",
			"label": "[100] Nt"
		}
	];
	dl_select.setJSON(jsonData);
};
